using System;using CodexStrip;
class StreamTest {static object Change(int revision,object state){return J.Obj("type","snapshot","revision",revision,"conversationState",state);}static int Main(){try{var turn=J.Obj("turnId","turn","turnStartedAtMs",100000,"status","inProgress","items",new[]{J.Obj("type","reasoning","text","must not show"),J.Obj("type","agentMessage","text","first reply"),J.Obj("type","commandExecution","output","must not show")});var root=J.Obj("title","Task","turnHistory",J.Obj("history",J.Obj("entitiesByKey",J.Obj("key",turn))),"requests",new object[0]);var s=new StreamState();s.Accept(Change(1,root),"owner","remote","id");if(s.Preview.Message!="first reply"||s.Preview.Status!="active")throw new Exception("projection");s.Accept(J.Obj("type","patches","baseRevision",1,"revision",2,"patches",new[]{J.Obj("op","replace","path",new object[]{"turnHistory","history","entitiesByKey","key","items",1,"text"},"value","new streamed text")}),"owner","remote","id");if(s.Preview.Message!="new streamed text")throw new Exception("delta");s.Accept(J.Obj("type","patches","baseRevision",2,"revision",3,"patches",new[]{J.Obj("op","add","path",new object[]{"requests",0},"value",J.Obj("params",J.Obj("questions",new[]{J.Obj("question","Choose now")})))}),"owner","remote","id");if(!s.Preview.QuestionPending||s.Preview.Message!="Choose now")throw new Exception("question");s.Accept(J.Obj("type","patches","baseRevision",3,"revision",4,"patches",new[]{J.Obj("op","remove","path",new object[]{"requests",0})}),"owner","remote","id");if(s.Preview.QuestionPending||s.Preview.Message!="new streamed text")throw new Exception("answer clearing");s.Accept(J.Obj("type","patches","baseRevision",2,"revision",9,"patches",new object[0]),"owner","remote","id");if(!s.Invalid)throw new Exception("missed revision detection");s.Accept(Change(10,root),"newowner","remote","id");if(s.Invalid||s.Owner!="newowner")throw new Exception("reconnect snapshot");Console.WriteLine("PASS: remote turn-history projection, incremental text, pending question and answer, revision gap detection, snapshot recovery");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}
